// Generates the review-metrics-*.json fixtures: GitHub REST responses trimmed to the fields the tool reads.
// Run: node tools/test/fixtures/make-review-metrics.mjs tools/test/fixtures
import fs from "node:fs";
const OUT = process.argv[2];
const NOW = Date.parse("2026-11-14T00:00:00Z");
const at = (days, hours = 0) => new Date(NOW - days * 86400000 + hours * 3600000).toISOString();
const rec = (pass, c, d, h, r, extra = "") =>
  ({ body: `## Merge gate: pass ${pass}\n\n| # | Proposed / judged | Verdict | Outcome |\n|---|---|---|---|\n${extra}\n\n<!-- gate: pass=${pass} critical=${c} downgraded=${d} high=${h} rejected=${r} -->` });
const chat = { body: "Looks good, merging soon." };
// pr(number, mergedDaysAgo | null, hoursToMerge)
const pr = (number, mergedDays, hours, title = `PR ${number}`) => {
  const merged = mergedDays == null ? null : at(mergedDays);
  const created = merged ? new Date(Date.parse(merged) - hours * 3600000).toISOString() : at(10);
  return { number, title, created_at: created, updated_at: merged ?? at(9), merged_at: merged };
};
const issue = (number, createdDays, closedDays = null, extra = {}) =>
  ({ number, title: `Issue ${number}`, created_at: at(createdDays), closed_at: closedDays == null ? null : at(closedDays), ...extra });
const P = (repo, q) => `repos/statewalker/${repo}/${q}`;
const pulls = (repo) => P(repo, "pulls?state=closed&sort=updated&direction=desc");
const comments = (repo, n) => P(repo, `issues/${n}/comments`);
const bugs = (repo) => P(repo, "issues?state=all&labels=bug");
const root = (label) => P("statewalker-root", `issues?state=open&labels=${label}`);
const write = (name, data) => fs.writeFileSync(`${OUT}/review-metrics-${name}.json`, JSON.stringify(data, null, 1) + "\n");

// busy: two projects, every case at once.
write("busy", {
  [pulls("webrun-files")]: [
    pr(10, 1, 2),   // two passes: critical fixed, then re-verified
    pr(11, 2, 4),   // a downgraded critical, speculative findings
    pr(13, 3, 6),   // override
    pr(14, 8, 8),   // no gate record
    pr(15, 9, 10),  // malformed record line only
    pr(12, 20, 12), // earlier half, clean
    pr(9, null, 0), // closed without merging
    pr(8, 40, 1),   // merged before the window
  ],
  [comments("webrun-files", 10)]: [rec(1, 1, 0, 0, 0, "| 1 | critical / critical | real: an override is a record saying \"overridden\" | fixed (abc123) |"), chat, rec(2, 0, 0, 0, 0)], // the word in prose is not an override
  [comments("webrun-files", 11)]: [rec(1, 0, 1, 1, 2, "| 1 | critical / high | real; no failure scenario | fixed |")],
  [comments("webrun-files", 13)]: [rec(1, 1, 0, 0, 0, "| 1 | critical / critical | real | overridden (the human's message) |")],
  [comments("webrun-files", 14)]: [chat],
  [comments("webrun-files", 15)]: [{ body: "pass 1\n\n<!-- gate: pass=x critical=0 -->" }],
  [comments("webrun-files", 12)]: [rec(1, 0, 0, 0, 0)],
  [bugs("webrun-files")]: [issue(31, 25), issue(32, 18), issue(33, 11, null, { pull_request: {} }), issue(34, 11), issue(35, 4)],
  [pulls("statewalker-db")]: [pr(5, 1, 24), pr(6, 16, 48)],
  [comments("statewalker-db", 5)]: [{ body: rec(1, 0, 0, 0, 0).body + "\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_\n" }], // footer appended by tooling
  [comments("statewalker-db", 6)]: [rec(1, 1, 0, 0, 0), rec(2, 1, 0, 0, 0), rec(3, 1, 0, 0, 0)], // pass 3 fixed a critical: not an override
  [bugs("statewalker-db")]: [issue(7, 25), issue(8, 18, 5), issue(9, 2)], // #9: a bug filed by hand, no review label, still deferred
  [root("bug,ready-for-agent")]: [
    issue(50, 30, null, { labels: [{ name: "bug" }, { name: "ready-for-agent" }] }),
    issue(51, 2, null, { pull_request: {}, labels: [{ name: "bug" }, { name: "ready-for-agent" }] }),
    issue(52, 3, null, { labels: [{ name: "bug" }, { name: "ready-for-agent" }, { name: "review-followup" }] }), // a root deferred bug, not an escalation
  ],
  [root("area:root")]: [{ number: 40, title: "Review metrics: critical findings rising in webrun-files" }, { number: 41, title: "Something else" }],
});

// noisy: many passes, mostly speculative findings.
write("noisy", {
  [pulls("httpeers")]: [pr(1, 1, 1), pr(2, 2, 3), pr(3, 3, 5)],
  [comments("httpeers", 1)]: [rec(1, 1, 0, 0, 3), rec(2, 0, 0, 0, 1)],
  [comments("httpeers", 2)]: [rec(1, 1, 0, 1, 2), rec(2, 1, 0, 0, 0), rec(3, 0, 0, 0, 1)],
  [comments("httpeers", 3)]: [rec(1, 0, 0, 1, 0)],
  [bugs("httpeers")]: [],
  [root("bug,ready-for-agent")]: [],
  [root("area:root")]: [{ number: 60, title: "Review metrics: speculative share above 30%" }],
});

// empty: nothing merged in the window.
write("empty", {
  [pulls("statewalker-fsm")]: [pr(4, 45, 2)],
  [bugs("statewalker-fsm")]: [],
  [root("bug,ready-for-agent")]: [],
  [root("area:root")]: [],
});
